              },
              "calendar_id": {
                "type": "string",
                "description": "Calendar ID of the event (e.g. email address from google_calendar_list_calendars). Defaults to the user's primary calendar."
              }
            },
            "required": [
              "event_id",
              "response_status"
            ]
          }
        }
      ]
    },
