                "description": "Filter the referencing pages by redirect status",
                "type": "string",
                "enum": [
                  "all",
                  "redirects",
                  "nonredirects"
                ]
              },
              "expandRedirects": {
                "default": true,
                "description": "When a referencing page is a redirect to the target, also return the pages that link through it. Applies to wikilinks and fileusage only.",
                "type": "boolean"
              },
              "limit": {
                "description": "Maximum referencing pages to return (1..500)",
                "type": "integer",
                "minimum": 1,
                "maximum": 500
